function valueColor(v){const max=Math.max(...(values.length?values:[8]));const p=Math.min(1,(v-1)/Math.max(1,max-1));return new THREE.Color().setHSL(.56-p*.42,.95,.56).getHex()}
function buildEvents(){let a=values.map((v,id)=>({v,id}));events=[];const n=a.length;for(let p=0;p<n-1;p++){events.push({type:'passStart',pass:p+1,line:1});let changed=false;for(let i=0;i<n-p-1;i++){events.push({type:'compare',a:a[i].id,b:a[i+1].id,i,pass:p+1,line:4});if(a[i].v>a[i+1].v){events.push({type:'swap',a:a[i].id,b:a[i+1].id,i,pass:p+1,line:5});[a[i],a[i+1]]=[a[i+1],a[i]];changed=true}}events.push({type:'lock',id:a[n-p-1].id,index:n-p-1,pass:p+1,line:1});events.push({type:'passEnd',pass:p+1,early:!changed,line:changed?3:6});if(!changed)break}events.push({type:'finish',line:6});}
function boot(){level=0;mode='learn';loadLevel(0);initThree();bindUI();}
function loadLevel(which){level=(which+LEVELS.length)%LEVELS.length;const l=LEVELS[level];values=[...l.values];original=values.map((v,i)=>({v,id:i}));comparisons=swaps=0;pass=1;eventIndex=0;playing=false;animating=false;paused=false;energy=86;combo=0;swapsLeft=Math.max(4,Math.floor(values.length*1.5));predictActive=false;$('#levelEyebrow').textContent=l.title.toUpperCase();$('#levelTitle').textContent=l.name;$('#levelSub').textContent=l.sub;$('#sector').textContent=`0${level+1} / 06`;$('#dots').innerHTML=LEVELS.map((_,i)=>`<i class="dot ${i<=level?'on':''}"></i>`).join('');$('#objective').innerHTML=level===3?'Meltdown in <b id="timer">45.0s</b> — sort fast.':level===4?'Equal signals must keep their <b>original order.</b>':level===5?'<b>Boss:</b> the loop stops one step too early. Find the bug.':'Compare neighbors. <b>Swap if left &gt; right.</b>';$('#modeDescription').textContent=level===3?'Timed run: clear all passes before the reactor melts down.':level===4?'Stable sort: equal values do not swap, preserving twin order.':level===5?'Bug report: loop bound is n-pass-2. One comparison is missing.':'The largest signal drifts right with each comparison. Sorted values lock into the gold zone.';$('#modeStatus').textContent=level===5?'Find the fault':'Target locked';$('#stageBadge').textContent=level===3?'MELTDOWN ARMED':level===5?'BOSS SIGNAL DETECTED':'SYSTEMS NOMINAL';$('#hint').textContent=mode==='manual'?'Choose SWAP or KEEP when the scanners light.':mode==='predict'?'Drag the mini signals into your predicted pass result.':'DRAG TO ORBIT · SPACE TO PAUSE';$('#narration').textContent=level===5?'The faulty bound skips the final neighbor comparison each pass. Identify the off-by-one before the boss escapes.':'Welcome, Cadet. Bubble sort compares neighbors and swaps them when they\'re out of order. Let\'s move the biggest signal to the end.';buildEvents();makeElements();refresh();setMode(mode);}
function refresh(){const fmt=n=>String(n).padStart(2,'0');$('#comparisons').textContent=fmt(comparisons);$('#swaps').textContent=fmt(swaps);$('#pass').innerHTML=`${fmt(Math.min(pass,values.length-1))} <small>/ ${fmt(values.length-1)}</small>`;$('#energy').style.width=`${energy}%`;$('#energyText').textContent=`${Math.round(energy)}%`;$('#xp').textContent=xp;$('#xpbar').style.width=`${Math.min(100,(xp%300)/3)}%`;$('#rank').textContent=xp>500?'ARCHITECT':xp>250?'ENGINEER':'CADET';$('#arrayMini').innerHTML=pillars.map((p,i)=>`<div class="mini-cell" draggable="true" data-index="${i}" style="border-color:${p.marking.material.opacity>.2?'#ffcf72':'#29516a'};color:${p.marking.material.opacity>.2?'#ffdb8d':'#a9eaff'}">${p.value}</div>`).join('');wireMini();}
function setMode(m){mode=m;$$('.navbtn').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));if(m==='manual')$('#objective').innerHTML='Your call: <b>SWAP</b> if left is greater. <b>KEEP</b> otherwise.';else if(m==='predict')$('#objective').innerHTML='Predict the end of one full pass. <b>Then run it.</b>';else if(m==='race')$('#objective').innerHTML='YOU vs <b>BUBBLE AI</b> — who sorts first?';else if(m==='learn')$('#objective').innerHTML='Compare neighbors. <b>Swap if left &gt; right.</b>';$('#hint').textContent=m==='manual'?'Choose SWAP or KEEP when the scanners light.':m==='predict'?'Drag the mini signals into your predicted pass result.':'DRAG TO ORBIT · SPACE TO PAUSE';$('#runPass').textContent=m==='manual'?'START DECISIONS':m==='predict'?'PREDICT PASS ↗':m==='race'?'START RACE ↗':'RUN PASS ↗';$('#liveLabel').textContent=m==='manual'?'YOUR MOVE':m==='predict'?'PREDICT':'LIVE';}
function bindUI(){$$('.navbtn').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$('#playBtn').onclick=()=>{playing=!playing;paused=!playing;$('#playBtn').textContent=playing?'Ⅱ':'▶';if(playing)advance()};$('#stepBtn').onclick=()=>{playing=false;paused=false;advance(true)};$('#stepBack').onclick=stepBackward;$('#restartBtn').onclick=()=>loadLevel(level);$('#shuffleBtn').onclick=()=>{const v=values.map(x=>x);for(let i=v.length-1;i>0;i--){const j=Math.random()*(i+1)|0;[v[i],v[j]]=[v[j],v[i]]}LEVELS[level].values=v;loadLevel(level)};$('#runPass').onclick=runPass;$('#nextLevel').onclick=()=>{hideToast();loadLevel(level+1)};$('#soundBtn').onclick=()=>{sound=!sound;$('#soundBtn').textContent=sound?'♫ SOUND ON':'♫ SOUND OFF'};$('#speed').oninput=e=>$('#speedText').textContent=`${(+e.target.value).toFixed(1)}×`;$('#swapDecision').onclick=()=>decide(true);$('#keepDecision').onclick=()=>decide(false);$('#toastBtn').onclick=()=>{hideToast();if(level<LEVELS.length-1)loadLevel(level+1)};document.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();$('#playBtn').click()}if(e.code==='ArrowRight')$('#stepBtn').click();if(e.code==='ArrowLeft')$('#stepBack').click()});}
function wireMini(){const cells=$$('.mini-cell');cells.forEach(cell=>{cell.ondragstart=e=>{e.dataTransfer.setData('text/plain',cell.dataset.index);cell.classList.add('dragging')};cell.ondragend=()=>cell.classList.remove('dragging');cell.ondragover=e=>e.preventDefault();cell.ondrop=e=>{e.preventDefault();const from=+e.dataTransfer.getData('text/plain'),to=+cell.dataset.index;if(Number.isInteger(from)&&from!==to){[pillars[from],pillars[to]]=[pillars[to],pillars[from]];reposition();refresh()}};cell.addEventListener('touchstart',()=>{cell.dataset.touchStart=Date.now()},{passive:true})})}
function reposition(){const n=pillars.length,spacing=Math.min(2.15,10.5/n),start=-(n-1)*spacing/2;pillars.forEach((p,i)=>{p.index=i;p.homeX=start+i*spacing;if(!animating)p.group.position.x=p.homeX})}
function stepBackward(){if(eventIndex<=0)return;playing=false;loadLevel(level);paused=true;for(let i=0;i<eventIndex-1;i++)applyEvent(events[i],true);eventIndex=Math.max(0,eventIndex-1);refresh()}
function runPass(){if(mode==='predict'){startPrediction();return}if(mode==='manual'){if(eventIndex===0||events[eventIndex]?.type==='passStart'){playing=true;paused=false;advance()}return}if(mode==='race'){startRace();return}playing=true;paused=false;advance()}
function advance(single=false){if(animating||paused)return;if(eventIndex>=events.length){playing=false;return}const ev=events[eventIndex++];if(mode==='manual'&&ev.type==='compare'){showDecision(ev);return}applyEvent(ev,false,()=>{if(ev.type==='passEnd'&&single){playing=false;return}if(single){playing=false;return}if(playing)setTimeout(()=>advance(),Math.max(100,420/speeds()))});}
function applyEvent(ev,instant=false,done){const setLine=()=>{$$('.code-line').forEach(l=>l.classList.toggle('active',+l.dataset.line===ev.line))};setLine();if(ev.type==='passStart'){pass=ev.pass;$('#narration').textContent=`Pass ${ev.pass}: scan the unsorted zone. Each comparison pushes the largest remaining value one step right.`;$('#modeStatus').textContent=`Pass ${ev.pass} in motion`;refresh();done&&done();return}
if(ev.type==='compare'){comparisons++;const a=pillars.find(p=>p.origin===ev.a),b=pillars.find(p=>p.origin===ev.b);focusPair(a,b,instant);$('#narration').textContent=`Compare ${a.value} and ${b.value}. ${a.value>b.value?'The left is larger — it must move right.':'They are in order — keep them where they are.'}`;soundFx('tick');refresh();if(!instant&&mode==='manual'){showDecision(ev);return}done&&done();return}
if(ev.type==='swap'){swaps++;const ia=pillars.findIndex(p=>p.origin===ev.a),ib=pillars.findIndex(p=>p.origin===ev.b);if(ia>=0&&ib>=0){[pillars[ia],pillars[ib]]=[pillars[ib],pillars[ia]];reposition();const a=pillars[ib],b=pillars[ia];$('#narration').textContent=`Swap! ${a.value} is larger, so it travels right. The unsorted boundary shrinks at the end of this pass.`;if(!instant){animateSwap(a,b,done);return}}soundFx('whoosh');refresh();done&&done();return}
if(ev.type==='lock'){const p=pillars.find(x=>x.origin===ev.id);if(p){p.marking.material.opacity=1;p.base.material.emissive.setHex(COLORS.gold);p.base.material.emissiveIntensity=.9;if(!instant){shockwave(p.group.position.x);soundFx('lock');$('#narration').textContent=`${p.value} is locked into its final slot. The gold zone is safe — next pass has one less stop.`;}}refresh();done&&done();return}
if(ev.type==='passEnd'){pass=ev.pass+1;if(ev.early)$('#narration').textContent='No swaps this pass! The array is already sorted. The swapped flag lets bubble sort exit early — best case O(n).';if(!instant&&ev.pass===values.length-1||!instant&&events[eventIndex]?.type==='finish'){playing=false;finishLevel();done&&done();return}refresh();done&&done();return}
if(ev.type==='finish'){playing=false;if(!instant)finishLevel();done&&done();return}}

